-- Catálogo aditivo de Ciências da Natureza. Fonte: https://api.bncc.dev/v1/habilidades?etapa=EM&area=cnt&limite=100

-- Restore area competency links and discipline availability without deleting data.
SELECT s.id, c.id
FROM curriculum_skills s
JOIN curriculum_areas a ON a.source_key = 'em-area-cnt'
JOIN curriculum_competencies c ON c.area_id = a.id
  AND c.number::text = substring(s.code FROM 8 FOR 1)
WHERE s.stage = 'Ensino Médio' AND s.code ~ '^EM13CNT[123][0-9]{2}$'
ON CONFLICT DO NOTHING;

SELECT d.id, s.id, d.created_by,
  'Habilidade da área BNCC Ciências da Natureza, disponível da 1ª à 3ª série.'
FROM pedagogical_disciplines d
JOIN curriculum_skills s ON s.stage = 'Ensino Médio'
  AND s.code ~ '^EM13CNT[123][0-9]{2}$'
WHERE d.stage = 'Ensino Médio' AND d.name IN ('Física', 'Biologia', 'Química')
ON CONFLICT (discipline_id, skill_id) DO NOTHING;
