INSERT INTO curriculum_areas(curriculum_version,source_key,name,stage) VALUES('BNCC-2018','em-area-cnt','Ciências da Natureza e suas Tecnologias','Ensino Médio') ON CONFLICT DO NOTHING;
INSERT INTO curriculum_competencies(area_id,number,source_key,description,source_metadata) SELECT a.id,1,'em-area-cnt-ce-01','Analisar fenômenos naturais e processos tecnológicos, com base nas interações e relações entre matéria e energia, para propor ações individuais e coletivas que aperfeiçoem processos produtivos, minimizem impactos socioambientais e melhorem as condições de vida em âmbito local, regional e global.','{"documento":"bncc-2018","fonte":"api.bncc.dev"}'::jsonb FROM curriculum_areas a WHERE a.curriculum_version='BNCC-2018' AND a.source_key='em-area-cnt' ON CONFLICT DO NOTHING;
INSERT INTO curriculum_competencies(area_id,number,source_key,description,source_metadata) SELECT a.id,2,'em-area-cnt-ce-02','Analisar e utilizar interpretações sobre a dinâmica da Vida, da Terra e do Cosmos para elaborar argumentos, realizar previsões sobre o funcionamento e a evolução dos seres vivos e do Universo, e fundamentar e defender decisões éticas e responsáveis.','{"documento":"bncc-2018","fonte":"api.bncc.dev"}'::jsonb FROM curriculum_areas a WHERE a.curriculum_version='BNCC-2018' AND a.source_key='em-area-cnt' ON CONFLICT DO NOTHING;
INSERT INTO curriculum_competencies(area_id,number,source_key,description,source_metadata) SELECT a.id,3,'em-area-cnt-ce-03','Investigar situações-problema e avaliar aplicações do conhecimento científico e tecnológico e suas implicações no mundo, utilizando procedimentos e linguagens próprios das Ciências da Natureza, para propor soluções que considerem demandas locais, regionais e/ou globais, e comunicar suas descobertas e conclusões a públicos variados, em diversos contextos e por meio de diferentes mídias e tecnologias digitais de informação e comunicação (TDIC).','{"documento":"bncc-2018","fonte":"api.bncc.dev"}'::jsonb FROM curriculum_areas a WHERE a.curriculum_version='BNCC-2018' AND a.source_key='em-area-cnt' ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT101','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar e representar, com ou sem o uso de dispositivos e de aplicativos digitais específicos, as transformações e conservações em sistemas que envolvam quantidade de matéria, de energia e de movimento para realizar previsões sobre seus comportamentos em situações cotidianas e em processos produtivos que priorizem o desenvolvimento sustentável, o uso consciente dos recursos naturais e a preservação da vida em todas as suas formas.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 4","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT102','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Realizar previsões, avaliar intervenções e/ou construir protótipos de sistemas térmicos que visem à sustentabilidade, considerando sua composição e os efeitos das variáveis termodinâmicas sobre seu funcionamento, considerando também o uso de tecnologias digitais que auxiliem no cálculo de estimativas e no apoio à construção dos protótipos.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 5","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT103','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Utilizar o conhecimento sobre as radiações e suas origens para avaliar as potencialidades e os riscos de sua aplicação em equipamentos de uso cotidiano, na saúde, no ambiente, na indústria, na agricultura e na geração de energia elétrica.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 6","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT104','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Avaliar os benefícios e os riscos à saúde e ao ambiente, considerando a composição, a toxicidade e a reatividade de diferentes materiais e produtos, como também o nível de exposição a eles, posicionando-se criticamente e propondo soluções individuais e/ou coletivas para seus usos e descartes responsáveis.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 7","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT105','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar os ciclos biogeoquímicos e interpretar os efeitos de fenômenos naturais e da interferência humana sobre esses ciclos, para promover ações individuais e/ ou coletivas que minimizem consequências nocivas à vida.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 8","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT106','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Avaliar, com ou sem o uso de dispositivos e aplicativos digitais, tecnologias e possíveis soluções para as demandas que envolvem a geração, o transporte, a distribuição e o consumo de energia elétrica, considerando a disponibilidade de recursos, a eficiência energética, a relação custo/benefício, as características geográficas e ambientais, a produção de resíduos e os impactos socioambientais e culturais.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 9","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT107','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Realizar previsões qualitativas e quantitativas sobre o funcionamento de geradores, motores elétricos e seus componentes, bobinas, transformadores, pilhas, baterias e dispositivos eletrônicos, com base na análise dos processos de transformação e condução de energia envolvidos - com ou sem o uso de dispositivos e aplicativos digitais -, para propor ações que visem a sustentabilidade.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 10","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 557"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT201','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar e discutir modelos, teorias e leis propostos em diferentes épocas e culturas para comparar distintas explicações sobre o surgimento e a evolução da Vida, da Terra e do Universo com as teorias científicas aceitas atualmente.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 11","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT202','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar as diversas formas de manifestação da vida em seus diferentes níveis de organização, bem como as condições ambientais favoráveis e os fatores limitantes a elas, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 12","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT203','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Avaliar e prever efeitos de intervenções nos ecossistemas, e seus impactos nos seres vivos e no corpo humano, com base nos mecanismos de manutenção da vida, nos ciclos da matéria e nas transformações e transferências de energia, utilizando representações e simulações sobre tais fatores, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 13","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT204','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Elaborar explicações, previsões e cálculos a respeito dos movimentos de objetos na Terra, no Sistema Solar e no Universo com base na análise das interações gravitacionais, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 14","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT205','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Interpretar resultados e realizar previsões sobre atividades experimentais, fenômenos naturais e processos tecnológicos, com base nas noções de probabilidade e incerteza, reconhecendo os limites explicativos das ciências.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 15","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT206','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Discutir a importância da preservação e conservação da biodiversidade, considerando parâmetros qualitativos e quantitativos, e avaliar os efeitos da ação humana e das políticas ambientais para a garantia da sustentabilidade do planeta.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 16","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT207','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Identificar, analisar e discutir vulnerabilidades vinculadas às vivências e aos desafios contemporâneos aos quais as juventudes estão expostas, considerando os aspectos físico, psicoemocional e social, a fim de desenvolver e divulgar ações de prevenção e de promoção da saúde e do bem-estar.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 17","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT208','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Aplicar os princípios da evolução biológica para analisar a história humana, considerando sua origem, diversificação, dispersão pelo planeta e diferentes formas de interação com a natureza, valorizando e respeitando a diversidade étnica e cultural humana.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 18","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT209','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar a evolução estelar associando-a aos modelos de origem e distribuição dos elementos químicos no Universo, compreendendo suas relações com as condições necessárias ao surgimento de sistemas solares e planetários, suas estruturas e composições e as possibilidades de existência de vida, utilizando representações e simulações, com ou sem o uso de dispositivos e aplicativos digitais (como softwares de simulação e de realidade virtual, entre outros).','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 19","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 559"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT301','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Construir questões, elaborar hipóteses, previsões e estimativas, empregar instrumentos de medição e representar e interpretar modelos explicativos, dados e/ou resultados experimentais para construir, avaliar e justificar conclusões no enfrentamento de situações-problema sob uma perspectiva científica.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 20","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT302','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Comunicar, para públicos variados, em diversos contextos, resultados de análises, pesquisas e/ou experimentos, elaborando e/ou interpretando textos, gráficos, tabelas, símbolos, códigos, sistemas de classificação e equações, por meio de diferentes linguagens, mídias, tecnologias digitais de informação e comunicação (TDIC), de modo a participar e/ou promover debates em torno de temas científicos e/ou tecnológicos de relevância sociocultural e ambiental.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 21","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT303','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Interpretar textos de divulgação científica que tratem de temáticas das Ciências da Natureza, disponíveis em diferentes mídias, considerando a apresentação dos dados, tanto na forma de textos como em equações, gráficos e/ou tabelas, a consistência dos argumentos e a coerência das conclusões, visando construir estratégias de seleção de fontes confiáveis de informações.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 22","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT304','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar e debater situações controversas sobre a aplicação de conhecimentos da área de Ciências da Natureza (tais como tecnologias do DNA, tratamentos com células-tronco, neurotecnologias, produção de tecnologias de defesa, estratégias de controle de pragas, entre outros), com base em argumentos consistentes, legais, éticos e responsáveis, distinguindo diferentes pontos de vista.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 23","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT305','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Investigar e discutir o uso indevido de conhecimentos das Ciências da Natureza na justificativa de processos de discriminação, segregação e privação de direitos individuais e coletivos, em diferentes contextos sociais e históricos, para promover a equidade e o respeito à diversidade.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 24","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT306','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Avaliar os riscos envolvidos em atividades cotidianas, aplicando conhecimentos das Ciências da Natureza, para justificar o uso de equipamentos e recursos, bem como comportamentos de segurança, visando à integridade física, individual e coletiva, e socioambiental, podendo fazer uso de dispositivos e aplicativos digitais que viabilizem a estruturação de simulações de tais riscos.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 25","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT307','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar as propriedades dos materiais para avaliar a adequação de seu uso em diferentes aplicações (industriais, cotidianas, arquitetônicas ou tecnológicas) e/ ou propor soluções seguras e sustentáveis considerando seu contexto local e cotidiano.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 26","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 561"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT308','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Investigar e analisar o funcionamento de equipamentos elétricos e/ou eletrônicos e sistemas de automação para compreender as tecnologias contemporâneas e avaliar seus impactos sociais, culturais e ambientais.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 27","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 562"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT309','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Analisar questões socioambientais, políticas e econômicas relativas à dependência do mundo atual em relação aos recursos não renováveis e discutir a necessidade de introdução de alternativas e novas tecnologias energéticas e de materiais, comparando diferentes tipos de motores e processos de produção de novos materiais.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Ciências da Natureza '', linha 28","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 562"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES('BNCC-2018','EM13CNT310','Ensino Médio','Ciências da Natureza e suas Tecnologias','Ensino Médio (sem seriação)','Investigar e analisar os efeitos de programas de infraestrutura e demais serviços básicos (saneamento, energia elétrica, transporte, telecomunicações, cobertura vacinal, atendimento primário à saúde e produção de alimentos, entre outros) e identificar necessidades locais e/ou regionais em relação a esses serviços, a fim de avaliar e/ou promover ações que contribuam para a melhoria na qualidade de vida e nas condições de saúde da população.','{"documento":"bncc-2018","arquivo":"BNCC_Ensino_Medio.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba ''Hab. de Linguagens e suas Tecn'', linha 3","localizador_pdf":"Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 562"}'::jsonb) ON CONFLICT DO NOTHING;
